#!/bin/bash
set -euo pipefail
# get-ai-router.sh — one-file bootstrap for free-tier-ai-router.
#
# Why this exists: the ClawHub registry entry for this skill is frozen at 1.6.1
# (newer versions publish successfully but never appear). This script installs
# the package, then upgrades it to the current, fully-fixed router.
#
#   bash get-ai-router.sh [API_KEY]
set -u
KEY="${1:-}"
DEST="${AI_ROUTER_DIR:-$HOME/.ai-router}"
mkdir -p "$DEST"
echo "🎛️  installing free-tier-ai-router -> $DEST"
if command -v npx >/dev/null 2>&1; then
  (cd "$DEST" && npx --yes clawhub@latest install free-tier-ai-router --no-input >/dev/null 2>&1) \
    && echo "  ✅ base package installed" || echo "  ⚠️  registry install failed; continuing"
fi
SK="$DEST/skills/free-tier-ai-router"
mkdir -p "$SK"
# The upgrade payload travels WITH this script (appended below the marker).
awk '/^#__PAYLOAD__$/{found=1;next} found' "$0" > "$SK/router_fixed.json"
if [ -s "$SK/router_fixed.json" ]; then
  python3 - "$SK" <<'EOF'
import base64,hashlib,json,os,sys
sk=sys.argv[1]
j=json.load(open(os.path.join(sk,'router_fixed.json')))
data=base64.b64decode(j['router_py_b64'])
assert hashlib.sha256(data).hexdigest()==j['sha256'], 'checksum mismatch'
open(os.path.join(sk,'router.py'),'wb').write(data)
print('  ✅ upgraded to current router (checksum verified)')
EOF
fi
cat > "$HOME/ai" <<EOF
#!/bin/bash
exec python3 "$SK/router.py" "\$@"
EOF
chmod +x "$HOME/ai"
echo "  ✅ entry point: $HOME/ai"
[ -n "$KEY" ] && python3 "$SK/router.py" --setup "$KEY"
echo "  run:  ai \"your question\"   ·   ai --doctor"
exit 0
#__PAYLOAD__
{"_comment": "Authoritative router.py; integrate.sh restores it when the registry serves a stale build.", "sha256": "207407a543cd987e1acffac0d52b03201e2253771655b38dd69dc25bdfbe0196", "router_py_b64": ""}